-- Check if there's a difference between joining through datalogger vs directly
SELECT COUNT(*) FROM container c 
JOIN sensordata s ON s.containlink = c.containregistry;

SELECT COUNT(*) FROM container c 
JOIN datalogger d ON d.containlog = c.containregistry;

SELECT COUNT(*) FROM container c 
JOIN sensordata s ON s.containlink = c.containregistry
JOIN datalogger d ON d.containlog = c.containregistry;
